package hn.uth.pm1ea0199.controller;
import android.Manifest;import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.widget.*;import hn.uth.pm1ea0199.dao.ContactoDAO;import hn.uth.pm1ea0199.model.Contacto;import hn.uth.pm1ea0199.view.Vistas;
public class LlamarActivity extends Activity {
 private Contacto c;
 @Override public void onCreate(Bundle s){super.onCreate(s);try(ContactoDAO dao=new ContactoDAO(this)){c=dao.buscar(getIntent().getLongExtra("id",-1));}if(c==null){finish();return;}LinearLayout l=Vistas.pagina(this,"Llamar contacto");setContentView(l);ImageView f=Vistas.foto(this,l);Vistas.mostrar(f,c.imagen);TextView t=new TextView(this);t.setText(c.nombre+"\n"+c.telefono+"\n"+c.pais);t.setTextSize(24);t.setPadding(0,24,0,24);l.addView(t);Vistas.boton(this,l,"Llamar").setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Confirmar llamada").setMessage("¿Desea llamar a "+c.nombre+"?").setNegativeButton("Cancelar",null).setPositiveButton("Sí, llamar",(d,w)->{if(checkSelfPermission(Manifest.permission.CALL_PHONE)==PackageManager.PERMISSION_GRANTED)llamar();else requestPermissions(new String[]{Manifest.permission.CALL_PHONE},20);}).show());Vistas.boton(this,l,"Volver").setOnClickListener(v->finish());}
 private void llamar(){try{startActivity(new Intent(Intent.ACTION_CALL,Uri.fromParts("tel",c.telefono,null)));}catch(SecurityException e){Vistas.alerta(this,"Se necesita el permiso de llamadas.");}catch(ActivityNotFoundException e){Vistas.alerta(this,"Este dispositivo no permite realizar llamadas. Prueba en un teléfono con SIM.");}}
 @Override public void onRequestPermissionsResult(int r,String[] permisos,int[] resultados){super.onRequestPermissionsResult(r,permisos,resultados);if(r==20){if(resultados.length>0&&resultados[0]==PackageManager.PERMISSION_GRANTED)llamar();else Vistas.alerta(this,"Permiso denegado. Puedes autorizarlo en Ajustes > Aplicaciones > Agenda de Contactos > Permisos.");}}
}
